package com.studenttong.mobile;
import android.content.*;import android.location.*;import android.os.*;import java.util.*;
/** Uses only official test provider APIs. Never replaces gps/network or hides mock flags. */
public final class MockLocationManager {
 public interface Events{void read(Location l);void failure(String reason);}
 final LocationManager manager;final MockLocationConfig config;final Events events;public final String provider="studenttong_"+UUID.randomUUID().toString().replace("-","");boolean registered;LocationListener listener;long published;
 public MockLocationManager(Context c,MockLocationConfig v,Events events){manager=(LocationManager)c.getSystemService(Context.LOCATION_SERVICE);config=v;this.events=events;}
 public void begin()throws Exception{if(manager.getAllProviders().contains(provider))throw new Exception("测试Provider名称冲突，未覆盖其他Provider");try{if(Build.VERSION.SDK_INT>=31){android.location.provider.ProviderProperties props=new android.location.provider.ProviderProperties.Builder().setHasAltitudeSupport(true).setHasSpeedSupport(true).setHasBearingSupport(true).setPowerUsage(android.location.provider.ProviderProperties.POWER_USAGE_LOW).setAccuracy(android.location.provider.ProviderProperties.ACCURACY_FINE).build();manager.addTestProvider(provider,props);}else manager.addTestProvider(provider,false,false,false,false,true,true,true,Criteria.POWER_LOW,Criteria.ACCURACY_FINE);registered=true;manager.setTestProviderEnabled(provider,true);listener=new LocationListener(){public void onLocationChanged(Location l){verify(l);}public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}};manager.requestLocationUpdates(provider,0,0,listener,Looper.getMainLooper());publish();}catch(Exception e){try{close();}catch(Exception ignored){}throw e;}}
 public void publish(){try{if(!registered)throw new Exception("Provider未注册");Location l=new Location(provider);l.setLatitude(config.point.latitude);l.setLongitude(config.point.longitude);l.setAccuracy((float)config.point.accuracy);l.setAltitude(config.altitude);l.setSpeed(config.speed);l.setBearing(config.bearing);l.setTime(System.currentTimeMillis());l.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());published=l.getElapsedRealtimeNanos();manager.setTestProviderLocation(provider,l);Location returned=manager.getLastKnownLocation(provider);if(returned!=null)verify(returned);}catch(Exception e){events.failure(e instanceof SecurityException?"系统撤销了模拟定位授权":"系统定位发布失败，请查看诊断");}}
 void verify(Location l){if(!registered||!provider.equals(l.getProvider())||!LocationModeManager.isMock(l)||l.getElapsedRealtimeNanos()<published||!SignLogic.fresh(l,SystemClock.elapsedRealtimeNanos()))return;float[] distance=new float[1];Location.distanceBetween(l.getLatitude(),l.getLongitude(),config.point.latitude,config.point.longitude,distance);if(distance[0]<=1)events.read(l);}
 public boolean registered(){return registered;}
 public void close()throws Exception{Exception error=null;if(listener!=null){manager.removeUpdates(listener);listener=null;}if(registered){try{manager.removeTestProvider(provider);registered=false;}catch(Exception e){error=e;}}if(error!=null)throw error;}
}
